// Le topic porte le siteId : sesame/{siteId}/doorbell/ring (§4).
const siteId = (msg.topic || '').split('/')[1];
if (!siteId || !msg.payload || !msg.payload.ringId) {
    node.warn('Sonnerie ignorée : topic ou payload invalide');
    return null;
}

msg.sesame = {
    siteId: siteId,
    title: 'Quelqu\'un sonne',
    body: 'Appui sur la sonnette du portail.'
};
node.status({ fill: 'blue', shape: 'dot', text: msg.payload.ringId });
return msg;

const crypto = global.get('crypto');
const fs = global.get('fs');

const KEY_FILE = '/data/firebase-service-account.json';
const AUD = 'https://oauth2.googleapis.com/token';
const SCOPE = 'https://www.googleapis.com/auth/firebase.messaging';

let key;
try {
    key = JSON.parse(fs.readFileSync(KEY_FILE, 'utf8'));
} catch (e) {
    node.error('Clé de compte de service illisible : ' + e.message, msg);
    return null;
}

// project_id vient du fichier de clé : une variable d'environnement de moins
// à tenir à jour, et aucun risque de désaccord entre les deux.
msg.sesame.projectId = key.project_id;

const b64 = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
const now = Math.floor(Date.now() / 1000);
const unsigned = b64({ alg: 'RS256', typ: 'JWT' }) + '.' + b64({
    iss: key.client_email,
    scope: SCOPE,
    aud: AUD,
    iat: now,
    exp: now + 3600
});
const signature = crypto.createSign('RSA-SHA256')
    .update(unsigned)
    .sign(key.private_key, 'base64url');

// Un jeton neuf à chaque sonnerie : on sonne rarement, et gérer un cache avec
// son expiration coûterait plus en complexité que l'échange lui-même.
msg.url = AUD;
msg.headers = { 'content-type': 'application/x-www-form-urlencoded' };
msg.payload = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion: unsigned + '.' + signature
}).toString();
return msg;

const token = msg.payload && msg.payload.access_token;
if (!token) {
    node.error('Jeton OAuth absent : ' + JSON.stringify(msg.payload).slice(0, 300), msg);
    return null;
}

msg.url = 'https://fcm.googleapis.com/v1/projects/' + msg.sesame.projectId + '/messages:send';
msg.headers = {
    'content-type': 'application/json',
    authorization: 'Bearer ' + token
};
msg.payload = {
    message: {
        // Topic FCM = siteId opaque : aucun identifiant utilisateur dans le
        // routage des messages (§10).
        topic: msg.sesame.siteId,
        // Bloc `notification` : Android l'affiche lui-même, app fermée, sans
        // avoir à réveiller notre code.
        notification: { title: msg.sesame.title, body: msg.sesame.body },
        // TTL 60 s : un téléphone hors ligne plus longtemps ne recevra pas
        // « Quelqu'un sonne » des heures après ; la sonnerie reste dans l'historique.
        android: { priority: 'HIGH', ttl: '60s' }
    }
};
return msg;

// Measurement gate_events, tags siteId et type (§9).
const parts = (msg.topic || '').split('/');
const siteId = parts[1];
const kind = parts[3]; // 'ring' ou 'state'
if (!siteId || !msg.payload) { return null; }

const esc = (s) => String(s).replace(/["\\]/g, '\\$&');

let type, fields;
if (kind === 'ring' && msg.payload.ringId) {
    type = 'ring';
    fields = 'ringId="' + esc(msg.payload.ringId) + '"';
} else if (kind === 'state' && msg.payload.state) {
    type = 'state';
    fields = 'state="' + esc(msg.payload.state) + '",seq=' + (parseInt(msg.payload.seq, 10) || 0) + 'i';
} else {
    node.warn('Évènement non historisé : ' + msg.topic);
    return null;
}

// ts vaut 0 tant que l'ESP32 n'a pas l'heure NTP : on date alors de la
// réception, sinon la mesure atterrirait en 1970 et fausserait l'historique.
const seconds = Number(msg.payload.ts) || 0;
const ns = seconds > 0
    ? BigInt(seconds) * 1000000000n
    : BigInt(Date.now()) * 1000000n;

// Jeton et bucket lus dans l'environnement : aucun secret dans flows.json (§10).
msg.url = 'http://influxdb:8086/api/v2/write'
    + '?org=' + encodeURIComponent(env.get('INFLUXDB_ORG'))
    + '&bucket=' + encodeURIComponent(env.get('INFLUXDB_BUCKET'))
    + '&precision=ns';
msg.headers = {
    authorization: 'Token ' + env.get('INFLUXDB_TOKEN'),
    'content-type': 'text/plain; charset=utf-8'
};
msg.payload = 'gate_events,siteId=' + siteId + ',type=' + type + ' ' + fields + ' ' + ns.toString();
return msg;

// from/to sont interpolés dans du Flux : on n'accepte qu'une durée
// relative (-24h) ou un instant RFC3339, jamais du texte libre. Sans ce
// filtre, un paramètre d'URL pourrait injecter du code Flux.
const SAFE = /^(-\d+[smhdw]|\d{4}-\d{2}-\d{2}T[0-9:.]+Z)$/;
const q = (msg.req && msg.req.query) || {};
const from = SAFE.test(q.from || '') ? q.from : '-7d';
const to = SAFE.test(q.to || '') ? q.to : 'now()';
const stop = to === 'now()' ? 'now()' : to;

msg.flux = 'from(bucket:"' + env.get('INFLUXDB_BUCKET') + '")'
    + ' |> range(start:' + from + ', stop:' + stop + ')'
    + ' |> filter(fn:(r) => r._measurement == "gate_events")'
    + ' |> pivot(rowKey:["_time"], columnKey:["_field"], valueColumn:"_value")'
    + ' |> sort(columns:["_time"], desc:true)'
    + ' |> limit(n:200)';

msg.url = 'http://influxdb:8086/api/v2/query?org=' + encodeURIComponent(env.get('INFLUXDB_ORG'));
msg.headers = {
    authorization: 'Token ' + env.get('INFLUXDB_TOKEN'),
    'content-type': 'application/vnd.flux',
    accept: 'application/csv'
};
msg.payload = msg.flux;
return msg;

// InfluxDB 2.x ne répond qu'en CSV annoté pour les requêtes Flux : les
// lignes '#' sont des métadonnées, et chaque table réémet son en-tête.
const rows = [];
let header = null;
for (const line of String(msg.payload).split('\n')) {
    const l = line.trim();
    if (!l || l.startsWith('#')) continue;
    const cells = l.split(',');
    if (cells[1] === 'result' && cells[2] === 'table') { header = cells; continue; }
    if (!header) continue;
    const row = {};
    header.forEach((name, i) => {
        if (name && name !== 'result' && name !== 'table') row[name] = cells[i];
    });
    rows.push(row);
}

const events = rows.filter((r) => r._time).map((r) => {
    const e = { ts: r._time, type: r.type, siteId: r.siteId };
    if (r.ringId) e.ringId = r.ringId;
    if (r.state) e.state = r.state;
    if (r.seq) e.seq = Number(r.seq);
    return e;
});

msg.statusCode = 200;
msg.headers = {
    'content-type': 'application/json; charset=utf-8',
    // CORS : permet de tester l'API depuis un navigateur (§9).
    'access-control-allow-origin': '*'
};
msg.payload = { count: events.length, events: events };
return msg;
